function hasRemoteDivergence(cwd: string): boolean {
  try {
    const upstream = execSync("git rev-parse --abbrev-ref --symbolic-full-name @{u}", {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    }).trim();
    if (!upstream) return false;
    const count = execSync(`git rev-list --count HEAD..@{u}`, {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    }).trim();
    return parseInt(count, 10) > 0;
  } catch {
    return false;
  }
}

function getTrackerCompletionStatus(
  stoppedReason: RalphLoopResult["stoppedReason"],
): "completed" | "failed" | "interrupted" {
  if (stoppedReason === "interrupted") return "interrupted";
  if (stoppedReason === "error") return "failed";
  return "completed";
}

export function classifyConsoleLogEntry(text: string): RunLogEntry {
  const workerMatch = text.match(/^\[#([^\]]+)\]\s([\s\S]*)$/);
  if (!workerMatch) {
    return { kind: "text", text };
  }

  return {
    kind: "issue-text",
    issueId: workerMatch[1],
    text: workerMatch[2],
  };
}

function attachWriterBackedConsole(
  enabled: boolean,
  write: (entry: RunLogEntry) => void,
): () => void {
  if (!enabled) {
    return () => {};
  }

  const original = {
    log: console.log,
    warn: console.warn,
    error: console.error,
  };
  const writeLine = (...args: unknown[]): void => {
    write(classifyConsoleLogEntry(`${format(...args)}\n`));
  };

  console.log = (...args: unknown[]) => writeLine(...args);
  console.warn = (...args: unknown[]) => writeLine(...args);
  console.error = (...args: unknown[]) => writeLine(...args);

  return () => {
    console.log = original.log;
    console.warn = original.warn;
    console.error = original.error;
  };
}

export function classifyLikelyCause(error: string | undefined, verified: boolean | undefined): string | null {
  if (verified === false) {
    return "verification failed";
  }
  if (!error) {
    return null;
  }

  if (error.startsWith("Failed to spawn ")) {
    return "CLI missing or failed to start";
  }
  if (error === "Pi protocol did not complete." || error === "Pi RPC protocol did not complete.") {
    return "agent disconnected before protocol completion";
  }
  if (error === "Pi RPC agent run did not complete.") {
    return "agent disconnected before finishing the run";
  }
  if (error === "force-kill" || error.includes("force-killed for context budget")) {
    return "context budget force-kill";
  }
  if (error.startsWith("Pi protocol error:") || error.startsWith("Pi protocol aborted:")) {
    return "agent protocol error";
  }
  if (/ exited with code /i.test(error)) {
    return "agent process exited unexpectedly";
  }
  if (/disconnect|disconnected/i.test(error)) {
    return "agent disconnected";
  }
  if (/manual-interrupted/i.test(error)) {
    return "manual interrupt";
  }
  if (/manual-skip/i.test(error)) {
    return "manual skip";
  }
  if (/manual-retry/i.test(error)) {
    return "manual retry";
  }
  return null;
}

export function buildFailureSummaryReport(
  processed: readonly IterationResult[],
  runLogFilePath: string | undefined,
): string | null {
  const failures = processed.filter((result) => !result.success || result.verified === false);
  if (failures.length === 0) {
    return null;
  }

  const lines = ["ralph-loop stopped with failed work.", "", "Failures:"];
  for (const failure of failures.slice(-5)) {
    lines.push(`- #${String(failure.issue.id)} ${failure.issue.title}`);
    const likelyCause = classifyLikelyCause(failure.error, failure.verified);
    if (likelyCause) {
      lines.push(`  likely cause: ${likelyCause}`);
    }
    if (failure.error) {
      lines.push(`  ${failure.error}`);
    } else if (failure.verified === false) {
      lines.push("  acceptance criteria not met");
    }
  }

  if (runLogFilePath) {
    lines.push("", `Run log: ${runLogFilePath}`);
    const recentLog = readRecentRunLog(runLogFilePath, 20);
    if (recentLog) {
      lines.push("", "Recent logs:", recentLog);
    }
  }

  return `${lines.join("\n")}\n`;
}

