export interface IssueSource {
  /**
   * Return the next issue to work on, or null when there are no more issues.
   * Called once per iteration at the start of each loop.
   *
   * @param inProgressIds - Optional list of issue IDs that are currently
   *   being processed and should be excluded from the result.
   */
  fetchNext(inProgressIds?: (string | number)[]): Promise<Issue | null>;

  /**
   * Called after the agent successfully finishes an iteration.
   * Use it to close/label the issue, remove it from a queue, etc.
   */
  markDone(issue: Issue): Promise<void>;

  /**
   * Optional: Snapshot all currently visible issue statuses at loop start.
   * Used by Force-Kill Undo to restore loop-touched issue IDs to their
   * loop-start statuses after repository rollback succeeds.
   */
  snapshotStatuses?(): Promise<IssueStatusSnapshot>;

  /**
   * Optional: Restore loop-touched issue IDs to their exact loop-start
   * statuses. Only called after repository rollback succeeds.
   * Restores status metadata only, not issue content, file location,
   * or non-status metadata.
   */
  restoreStatuses?(snapshot: IssueStatusSnapshot, touchedIssueIds: (string | number)[]): Promise<void>;

  /**
   * Optional: Preview the next issue without reserving, removing, locking,
   * or otherwise mutating source state. Returns the same issue that
   * fetchNext would return for the same inProgressIds, but does not
   * change the source's internal state.
   */
  peekNext?(inProgressIds?: (string | number)[]): Promise<Issue | null>;

  /**
   * Optional: Check whether an issue with the given ID has already been
   * marked done by this source. Used during recovery to detect completion
   * state without retrying completion marking.
   */
  isDone?(issueId: string | number): Promise<boolean>;
}

